{"path": "affine_cipher.py", "content": "from math import gcd

M = 26
GROUP_SIZE = 5


def _mmi(a, m=M):
    if gcd(a, m) != 1:
        raise ValueError("a and m must be coprime.")
    return pow(a, -1, m)


def _translate(text, transform):
    result = []
    for char in text.lower():
        if char.isascii() and char.isalpha():
            result.append(chr(transform(ord(char) - ord("a")) + ord("a")))
        elif char.isascii() and char.isdigit():
            result.append(char)
    return "".join(result)


def encode(plain_text, a, b):
    _mmi(a)
    cipher = _translate(plain_text, lambda i: (a * i + b) % M)
    return " ".join(cipher[i:i + GROUP_SIZE] for i in range(0, len(cipher), GROUP_SIZE))


def decode(ciphered_text, a, b):
    inverse = _mmi(a)
    return _translate(ciphered_text, lambda y: (inverse * (y - b)) % M)
